package com.ruoyi.metal.service;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.util.*;
class SemiMeasurementRulesTest {
 @Test void absentModePreservesPiece(){assertFalse(SemiMeasurementRules.weight(Map.of()));}
 @Test void weightReferenceIsOptionalAndNeverDefaultsToOne(){assertNull(SemiMeasurementRules.reference(null));assertEquals(33L,SemiMeasurementRules.reference(33L));}
 @Test void illegalReferenceRejected(){for(long n:new long[]{0,-1,1000001})assertThrows(RuntimeException.class,()->SemiMeasurementRules.reference(n));}
 @Test void weightReleaseUsesOnlyMass(){assertDoesNotThrow(()->SemiMeasurementRules.requireWeight(new BigDecimal("600"),new BigDecimal("100")));assertThrows(RuntimeException.class,()->SemiMeasurementRules.requireWeight(new BigDecimal("600"),new BigDecimal("601")));}
 @Test void unknownReferencesRemainUnknown(){assertNull(SemiMeasurementRules.referenceBalance(33L,null,false,false));assertNull(SemiMeasurementRules.referenceBalance(null,1L,true,false));assertNull(SemiMeasurementRules.referenceBalance(1L,3L,true,false));assertEquals(32L,SemiMeasurementRules.referenceBalance(33L,1L,true,false));assertNull(SemiMeasurementRules.referenceBalance(33L,1L,true,true));}
 @Test void rejectsUnknownModes(){assertThrows(RuntimeException.class,()->SemiMeasurementRules.mode("KG"));}
 @Test void weightReportHasRealLossRateWithoutFakeCompletedPieces(){var b=new HashMap<String,Object>();b.put("measurementMode","WEIGHT");b.put("status","SETTLED");b.put("semiIssuedWeight","400");b.put("semiReturnedWeight","50");b.put("outputWeight","340");b.put("outputQuantity",0);b.put("reportId",1);b.put("reportIssuedWeight","400");b.put("reportReturnedWeight","390");b.put("reportLossWeight","10");b.put("reportCompletedQuantity",0);b.put("reportAverageLoss","0");b.put("documentCount",3);var r=ProcessConsumptionService.calculateBatch(b);assertEquals("SETTLED",r.get("state"));assertEquals("2.86",r.get("lossRatePercent"));assertNull(r.get("averageLoss"));assertNull(r.get("settledCompletedQuantity"));}
 @Test void laterWeightStageStillNeedsActualUpstreamSemi(){assertThrows(RuntimeException.class,()->SemiMeasurementRules.requireIntermediateInput(2,BigDecimal.ZERO));assertDoesNotThrow(()->SemiMeasurementRules.requireIntermediateInput(2,new BigDecimal("0.000001")));assertDoesNotThrow(()->SemiMeasurementRules.requireIntermediateInput(1,BigDecimal.ZERO));}
 @Test void weightSummaryRetainsValidSettledLoss(){var b=new HashMap<String,Object>();b.put("measurementMode","WEIGHT");b.put("status","SETTLED");b.put("state","SETTLED");b.put("settledLossWeight","10.000000");b.put("settledCompletedQuantity",null);b.put("netInputWeight","350");b.put("lossRatePercent","2.857143");b.put("reportThresholdValue","5");b.put("warnings",List.of());var r=ProcessConsumptionService.summarize(List.of(b));assertEquals("10.000000",r.get("settledLossWeight"));assertNotNull(r.get("reportStatus"));assertNull(r.get("settledCompletedQuantity"));}
 @Test void pieceCreditStopsAtActualWeightBoundary(){assertFalse(SemiMeasurementRules.pieceCreditApplies(List.of("PIECE","WEIGHT","PIECE","PIECE"),1,4));assertFalse(SemiMeasurementRules.pieceCreditApplies(List.of("WEIGHT","PIECE","PIECE"),1,3));assertTrue(SemiMeasurementRules.pieceCreditApplies(List.of("PIECE","WEIGHT","PIECE","PIECE"),3,4));assertTrue(SemiMeasurementRules.pieceCreditApplies(List.of("PIECE","PIECE"),1,2));}
 @Test void positivePowderStockWithNoPiecesIsConsistent(){assertTrue(SemiMeasurementRules.stockConsistent(Map.of("measurement_mode","WEIGHT","quantity",0,"net_weight","250")));assertFalse(SemiMeasurementRules.stockConsistent(Map.of("measurement_mode","PIECE","quantity",0,"net_weight","250")));}
}
